        if (Test-Path $agCatalog) {
            $cat = Get-Content $agCatalog -Raw | ConvertFrom-Json
            if ($cat.skills) {
                foreach ($prop in $cat.skills.PSObject.Properties) {
                    if ($prop.Name -in @("SyncRoot", "Count", "IsFixedSize", "IsReadOnly", "IsSynchronized", "Keys", "Values")) { continue }
                    $name = $prop.Name
                    $descStr = if ($prop.Value.description) { [string]$prop.Value.description } else { "" }
                    if ($name -match $Query -or $descStr -match $Query) {
                        $shortDesc = if ($descStr.Length -gt 80) { $descStr.Substring(0, 80) + "..." } else { $descStr }
                        $results += [PSCustomObject]@{
                            Source = "Antigravity Vault"
                            Name = $name
                            Description = $shortDesc
                            Path = Join-Path $VaultsDir "antigravity-skills\skills\$name"
                        }
                    }
                }
            }
        }"

