"# Waits for a user prompt submitted from the 3D J.A.R.V.I.S. UI and exits
# so Antigravity automatically wakes up and executes it with the active LLM!
$pendingPromptFile = Join-Path $PSScriptRoot "pending_prompt.json"
while ($true) {
  if (Test-Path $pendingPromptFile) {
    try {
      $raw = Get-Content $pendingPromptFile -Raw -Encoding UTF8
      Remove-Item $pendingPromptFile -Force -ErrorAction SilentlyContinue
      Write-Output "JARVIS_UI_PROMPT: $raw"
      exit 0
    } catch {}
  }
  Start-Sleep -Milliseconds 300
}
"

"param([string]$Event = "PreInvocation")
$ErrorActionPreference = "SilentlyContinue"
$inputJson = [Console]::In.ReadToEnd()
if (-not [string]::IsNullOrWhiteSpace($inputJson)) {
  try {
    $obj = $inputJson | ConvertFrom-Json
    $repoRoot = Split-Path $PSScriptRoot -Parent
    $stateFile = Join-Path $repoRoot "live_hook_state.json"
    $out = @{
      event = $Event
      timestamp = (Get-Date).ToString("o")
      conversationId = $obj.conversationId
      modelName = $obj.modelName
      lastUserInput = $obj.lastUserInput
      toolName = if ($obj.toolCall) { $obj.toolCall.name } else { "" }
    }
    $out | ConvertTo-Json -Compress | Set-Content -Path $stateFile -Encoding UTF8
  } catch {}
}

if ($Event -eq "PreToolUse") {
  Write-Output '{"decision":"allow"}'
} else {
  Write-Output '{}'
}
"

